// 6. Code: Validate Classification — enforce schema and confidence constraints
const response = $input.first().json;
const prep = $('Code: Validate Redaction/Normalize Feedback').first().json;

let aiParsed = null;
try {
  const rawText = response.candidates?.[0]?.content?.parts?.[0]?.text;
  if (rawText) {
    aiParsed = JSON.parse(rawText);
  }
} catch (e) {
  aiParsed = null;
}

let sentiment = 'NEUTRAL';
let category = 'General';
let urgency = 'LOW';
let escalationRequired = false;
let escalationReason = null;

if (aiParsed && aiParsed.sentiment) {
  sentiment = ['POSITIVE', 'NEUTRAL', 'NEGATIVE'].includes(aiParsed.sentiment) ? aiParsed.sentiment : 'NEUTRAL';
  category = aiParsed.category || 'General';
  urgency = ['LOW', 'MEDIUM', 'HIGH', 'CRITICAL'].includes(aiParsed.urgency) ? aiParsed.urgency : 'LOW';
  escalationRequired = Boolean(aiParsed.escalationRequired || urgency === 'CRITICAL' || urgency === 'HIGH');
  escalationReason = aiParsed.escalationReason || (escalationRequired ? 'High urgency customer feedback requires immediate operational follow-up' : null);
} else {
  // Deterministic Fallback if Gemini rate-limits or interrupts
  const text = (prep.normalizedSafeContent || '').toLowerCase();
  if (text.includes('urgent') || text.includes('broken') || text.includes('timeout') || text.includes('fail') || text.includes('cancel')) {
    sentiment = 'NEGATIVE';
    category = 'Product Quality';
    urgency = 'HIGH';
    escalationRequired = true;
    escalationReason = 'Critical operational keywords detected in feedback';
  } else if (text.includes('great') || text.includes('excellent') || text.includes('love') || text.includes('thanks')) {
    sentiment = 'POSITIVE';
    category = 'Customer Support';
    urgency = 'LOW';
    escalationRequired = false;
  }
}

return [{
  json: {
    feedbackId: prep.feedbackId,
    customerId: prep.customerId,
    workflowRunId: prep.workflowRunId,
    sentiment,
    category,
    urgency,
    escalationRequired,
    escalationReason,
    rawAIOutput: aiParsed || response
  }
}];

// 7. Code: Determine Priority/SLA — map categories/severity to documented handling policy
const item = $input.first().json;

let taskPriority = 'MEDIUM';
let slaHours = 24;

if (item.urgency === 'CRITICAL') {
  taskPriority = 'CRITICAL';
  slaHours = 4;
} else if (item.urgency === 'HIGH' || item.sentiment === 'NEGATIVE') {
  taskPriority = 'HIGH';
  slaHours = 8;
} else if (item.urgency === 'LOW' && item.sentiment === 'POSITIVE') {
  taskPriority = 'LOW';
  slaHours = 72;
}

const dueDate = new Date();
dueDate.setHours(dueDate.getHours() + slaHours);

return [{
  json: {
    ...item,
    taskPriority,
    slaHours,
    dueAt: dueDate.toISOString(),
    idempotencyKey: `feedback-task-${item.feedbackId}`
  }
}];

